WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_ms_ip_colleague'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '与同事相处', 'kp-ms-ip-colleague', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "人际交往：与同事相处"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "工作第一，大事讲原则，小事讲风格。多揽活，少抢功。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、常见矛盾化解"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "老同事倚老卖老不干活：自己多承担一点，遇到困难主动向老同事请教（满足他们的自尊心），用诚恳的态度感化他们。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "同事背后说你坏话：有则改之，无则加勉。绝不撕破脸对骂。在工作中用出色的业绩和宽容的态度证明自己的人品。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "同事推诿扯皮：自己先顶上保证工作进度。事后在复盘会上明确各自的权责边界，做到“先补台，后分责”。"}]}]}]}]}$$ AS jsonb), NULL, '与同事相处的核心考点与高分作答技巧。', category_node.id, CAST('["面试", "人际交往", "同事关系"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ms_ip_colleague", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
